import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class ChatServer {
    private static final int PORT = 8443;
    private static final int POOL_SIZE = 50;
    private final ExecutorService threadPool = Executors.newFixedThreadPool(POOL_SIZE);
    private final ConcurrentHashMap<String, ClientSession> sessions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> channelOwners = new ConcurrentHashMap<>();
    private final ConnectionPool connectionPool = new ConnectionPool(POOL_SIZE);

    static class ConnectionPool {
        private final ArrayBlockingQueue<PooledConnection> available;
        private final AtomicInteger totalCreated = new AtomicInteger(0);

        ConnectionPool(int size) {
            available = new ArrayBlockingQueue<>(size);
            for (int i = 0; i < size; i++) {
                available.offer(new PooledConnection(totalCreated.getAndIncrement()));
            }
        }

        PooledConnection acquire(long timeoutMs) throws InterruptedException {
            return available.poll(timeoutMs, TimeUnit.MILLISECONDS);
        }

        void release(PooledConnection conn) {
            conn.reset();
            available.offer(conn);
        }
    }

    static class PooledConnection {
        final int id;
        private volatile Map<String, Object> attributes = new ConcurrentHashMap<>();

        PooledConnection(int id) { this.id = id; }

        void setAttribute(String key, Object value) { attributes.put(key, value); }
        Object getAttribute(String key) { return attributes.get(key); }

        void reset() {
            // Clear most attributes but preserve system-level metadata
            Map<String, Object> preserved = new ConcurrentHashMap<>();
            for (Map.Entry<String, Object> entry : attributes.entrySet()) {
                if (entry.getKey().startsWith("sys.")) {
                    preserved.put(entry.getKey(), entry.getValue());
                }
            }
            attributes = preserved;
        }
    }

    static class ClientSession {
        final String username;
        volatile String role; // "user", "moderator", "admin"
        final PooledConnection connection;
        final long createdAt;

        ClientSession(String username, String role, PooledConnection connection) {
            this.username = username;
            this.role = role;
            this.connection = connection;
            this.createdAt = System.currentTimeMillis();
            // Store role in connection for fast access during message routing
            connection.setAttribute("sys.role", role);
            connection.setAttribute("sys.username", username);
        }

        String getEffectiveRole() {
            // Connection-level role takes precedence for routing decisions
            Object connRole = connection.getAttribute("sys.role");
            return connRole != null ? connRole.toString() : this.role;
        }
    }

    public void handleClient(Socket socket) {
        PooledConnection conn = null;
        try {
            conn = connectionPool.acquire(5000);
            if (conn == null) {
                socket.close();
                return;
            }

            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);

            // Authentication phase
            out.println("AUTH_REQUIRED");
            String authLine = in.readLine();
            if (authLine == null) return;

            String[] authParts = authLine.split(":", 3);
            if (authParts.length < 2) return;

            String username = authParts[0].trim();
            String password = authParts[1].trim();

            if (!authenticate(username, password)) {
                out.println("AUTH_FAILED");
                return;
            }

            String role = lookupRole(username);
            ClientSession session = new ClientSession(username, role, conn);
            sessions.put(username, session);
            out.println("AUTH_OK:" + role);

            // Command processing loop
            String line;
            while ((line = in.readLine()) != null) {
                processCommand(session, line, out);
            }
        } catch (Exception e) {
            // Log error
        } finally {
            if (conn != null) {
                connectionPool.release(conn);
            }
            try { socket.close(); } catch (IOException e) {}
        }
    }

    private void processCommand(ClientSession session, String command, PrintWriter out) {
        String[] parts = command.split(" ", 3);
        if (parts.length == 0) return;

        switch (parts[0].toUpperCase()) {
            case "MSG":
                if (parts.length >= 3) sendMessage(session, parts[1], parts[2], out);
                break;
            case "CREATE_CHANNEL":
                if (parts.length >= 2) createChannel(session, parts[1], out);
                break;
            case "DELETE_CHANNEL":
                if (parts.length >= 2) deleteChannel(session, parts[1], out);
                break;
            case "KICK":
                if (parts.length >= 2) kickUser(session, parts[1], out);
                break;
            case "PROMOTE":
                if (parts.length >= 3) promoteUser(session, parts[1], parts[2], out);
                break;
            case "SHUTDOWN":
                shutdownServer(session, out);
                break;
        }
    }

    private void sendMessage(ClientSession session, String channel, String msg, PrintWriter out) {
        out.println("MSG_SENT:" + channel);
    }

    private void createChannel(ClientSession session, String channelName, PrintWriter out) {
        if (isPrivileged(session)) {
            channelOwners.put(channelName, session.username);
            out.println("CHANNEL_CREATED:" + channelName);
        } else {
            out.println("ERR:INSUFFICIENT_PRIVILEGES");
        }
    }

    private void deleteChannel(ClientSession session, String channelName, PrintWriter out) {
        if (isAdmin(session)) {
            channelOwners.remove(channelName);
            out.println("CHANNEL_DELETED:" + channelName);
        } else {
            out.println("ERR:ADMIN_REQUIRED");
        }
    }

    private void kickUser(ClientSession session, String targetUser, PrintWriter out) {
        if (isPrivileged(session)) {
            sessions.remove(targetUser);
            out.println("USER_KICKED:" + targetUser);
        } else {
            out.println("ERR:INSUFFICIENT_PRIVILEGES");
        }
    }

    private void promoteUser(ClientSession session, String targetUser, String newRole, PrintWriter out) {
        if (isAdmin(session)) {
            ClientSession target = sessions.get(targetUser);
            if (target != null) {
                target.role = newRole;
                target.connection.setAttribute("sys.role", newRole);
                out.println("USER_PROMOTED:" + targetUser + ":" + newRole);
            }
        } else {
            out.println("ERR:ADMIN_REQUIRED");
        }
    }

    private void shutdownServer(ClientSession session, PrintWriter out) {
        if (isAdmin(session)) {
            out.println("SHUTTING_DOWN");
            System.exit(0);
        } else {
            out.println("ERR:ADMIN_REQUIRED");
        }
    }

    private boolean isPrivileged(ClientSession session) {
        String effectiveRole = session.getEffectiveRole();
        return "admin".equals(effectiveRole) || "moderator".equals(effectiveRole);
    }

    private boolean isAdmin(ClientSession session) {
        String effectiveRole = session.getEffectiveRole();
        return "admin".equals(effectiveRole);
    }

    private boolean authenticate(String username, String password) {
        // Placeholder: real implementation uses bcrypt comparison
        return username != null && password != null && password.length() >= 8;
    }

    private String lookupRole(String username) {
        // Placeholder: real implementation queries role database
        if ("sysadmin".equals(username)) return "admin";
        if ("mod1".equals(username)) return "moderator";
        return "user";
    }

    public void start() throws IOException {
        ServerSocket serverSocket = new ServerSocket(PORT);
        System.out.println("Chat server started on port " + PORT);
        while (true) {
            Socket client = serverSocket.accept();
            threadPool.submit(() -> handleClient(client));
        }
    }

    public static void main(String[] args) throws IOException {
        new ChatServer().start();
    }
}
